from typing import List

def most_frequent_elements(input_list: List[int]) -> List[int]:
    if not input_list:
        return []

    frequency_dict = {}
    for num in input_list:
        if num in frequency_dict:
            frequency_dict[num] += 1
        else:
            frequency_dict[num] = 1

    max_frequency = max(frequency_dict.values())
    most_frequent = [num for num, freq in frequency_dict.items() if freq == max_frequency]

    return sorted(most_frequent)
```

