def find_all_anagrams(s: str, p: str):
    from collections import Counter

    if len(s) < len(p):
        return []

    p_count = Counter(p)
    s_count = Counter()

    result = []

    for i in range(len(p)):
        s_count[s[i]] += 1

    if s_count == p_count:
        result.append(0)

    for i in range(len(p), len(s)):
        s_count[s[i]] += 1
        s_count[s[i - len(p)]] -= 1

        if s_count[s[i - len(p)]] == 0:
            del s_count[s[i - len(p)]]

        if s_count == p_count:
            result.append(i - len(p) + 1)

    return result
```

