    result = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            for k in range(2):
                result[i][j] += a[i][k] * b[k][j]
    return result

def matrix_power(matrix, n):
    if n == 0 or n == 1:
        return matrix
    else:
        temp = matrix_power(matrix, n // 2)
        result = matrix_multiply(temp, temp)
        if n % 2 == 0:
            return result
        else:
            return matrix_multiply(result, matrix)

def optimized_fibonacci(n: int) -> int:
    if n <= 1:
        return n

    F = [[1, 1], [1, 0]]
    result = matrix_power(F, n - 1)

    return result[0][0]
