def optimized_fibonacci(n: int) -> int:
    if n <= 1:
        return n

    def multiply(mat1, mat2):
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] += mat1[i][k] * mat2[k][j]
        return result

    def matrix_power(mat, n):
        if n == 0 or n == 1:
            return mat
        temp = matrix_power(mat, n // 2)
        result = multiply(temp, temp)
        if n % 2 == 1:
            result = multiply(result, [[1, 1], [1, 0]])
        return result

    F = [[1, 1], [1, 0]]
    result = matrix_power(F, n - 1)
    return result[0][0]
