from typing import List
from math import gcd

def find_lcm(numbers: List[int]) -> int:
    def lcm(a: int, b: int) -> int:
        return abs(a * b) // gcd(a, b)

    current_lcm = numbers[0]
    for num in numbers[1:]:
        current_lcm = lcm(current_lcm, num)

    return current_lcm
