def custom_caesar_cipher(message, shift):
    def shift_char(c, shift):
        if 'a' <= c <= 'z':
            return chr(((ord(c) - ord('a') + shift) % 26) + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr(((ord(c) - ord('A') + shift) % 26) + ord('A'))
        else:
            return c

    encrypted_message = ''.join(shift_char(c, shift) for c in message)
    return encrypted_message

# Example usage and testing
print(custom_caesar_cipher("Hello, World!", 3))  # "Khoor, Zruog!"
print(custom_caesar_cipher("abcdef", 1))  # "bcdefg"
print(custom_caesar_cipher("ABC XYZ", 4))  # "EFG BCD"
print(custom_caesar_cipher("", 5))  # ""
```

