def shift_string(s, n):
    result = ""
    for char in s:
        if 'a' <= char <= 'z':
            shifted = ord(char) + n
            if shifted > ord('z'):
                shifted = shifted - 26
            result += chr(shifted)
        elif 'A' <= char <= 'Z':
            shifted = ord(char) + n
            if shifted > ord('Z'):
                shifted = shifted - 26
            result += chr(shifted)
        else:
            result += char
    return result
```

