def is_anagram(s1, s2):
    # Filter out non-alphabetic characters and convert to lowercase
    filtered_s1 = ''.join(filter(str.isalpha, s1)).lower()
    filtered_s2 = ''.join(filter(str.isalpha, s2)).lower()

    # If the lengths of the filtered strings are different, they cannot be anagrams
    if len(filtered_s1) != len(filtered_s2):
        return False

    # Count the frequency of each character in both strings
    count_s1 = {}
    count_s2 = {}

    for char in filtered_s1:
        if char in count_s1:
            count_s1[char] += 1
        else:
            count_s1[char] = 1

    for char in filtered_s2:
        if char in count_s2:
            count_s2[char] += 1
        else:
            count_s2[char] = 1

    # Compare the frequency dictionaries
    if count_s1 == count_s2:
        return True
    else:
        return False
```

