from typing import Dict, List, Tuple
import heapq

def shortest_path_with_stops(graph: Dict[str, List[Tuple[str, int]]], start: str, end: str, max_stops: int) -> int:
    if start not in graph or end not in graph:
        return -1

    # Priority queue: (current_weight, current_node, stops_used)
    pq = [(0, start, 0)]
    visited = {}

    while pq:
        current_weight, current_node, stops_used = heapq.heappop(pq)

        if current_node == end:
            return current_weight

        if (current_node, stops_used) in visited and visited[(current_node, stops_used)] <= current_weight:
            continue

        visited[(current_node, stops_used)] = current_weight

        if stops_used < max_stops:
            for neighbor, weight in graph[current_node]:
                heapq.heappush(pq, (current_weight + weight, neighbor, stops_used + 1))

    return -1
```

