    if max_stops < 0:
        return -1

    # Priority queue to store (current_weight, current_node, current_stops)
    pq = deque([(0, start, 0)])
    visited = defaultdict(lambda: float('inf'))

    while pq:
        current_weight, current_node, current_stops = pq.popleft()

        if current_node == end:
            return current_weight

        if current_stops > max_stops:
            continue

        for neighbor, weight in graph[current_node]:
            new_weight = current_weight + weight
            new_stops = current_stops + 1

            if new_weight < visited[neighbor] or new_stops <= visited[neighbor]:
                visited[neighbor] = new_stops
                pq.append((new_weight, neighbor, new_stops))

    return -1
```

