from collections import defaultdict, deque

def shortest_path_with_stops(graph: dict, start: str, end: str, max_stops: int) -> int:
    if start not in graph or end not in graph:
        return -1

    if max_stops == 0:
        if (end, 0) in graph[start]:
            return graph[start][(end, 0)]
        else:
            return -1

    queue = deque([(start, 0, 0)])  # (current_node, current_weight, current_stops)
    visited = set()

    while queue:
        current_node, current_weight, current_stops = queue.popleft()

        if current_node == end:
            return current_weight

        if (current_node, current_stops) in visited:
            continue

        visited.add((current_node, current_stops))

        if current_stops < max_stops:
            for neighbor, weight in graph[current_node]:
                queue.append((neighbor, current_weight + weight, current_stops + 1))

    return -1
```

