class CoinChange:
    def __init__(self, coins: list[int]):
        self.coins = coins

    def min_coins(self, amount: int) -> int:
        # Create a list to store the minimum coins needed for each amount up to the given amount
        dp = [float('inf')] * (amount + 1)
        dp[0] = 0  # Base case: 0 coins are needed to make amount 0

        # Iterate over each amount from 1 to the given amount
        for i in range(1, amount + 1):
            # Check each coin denomination
            for coin in self.coins:
                if i - coin >= 0:
                    dp[i] = min(dp[i], dp[i - coin] + 1)

        # If dp[amount] is still infinity, it means it's not possible to make the amount with the given coins
        return dp[amount] if dp[amount] != float('inf') else -1
