from typing import List

def max_robbery_in_circle(nums: List[int]) -> int:
    def rob(nums: List[int]) -> int:
        if not nums:
            return 0
        if len(nums) == 1:
            return nums[0]

        dp = [0] * len(nums)
        dp[0] = nums[0]
        dp[1] = max(nums[0], nums[1])

        for i in range(2, len(nums)):
            dp[i] = max(dp[i-1], dp[i-2] + nums[i])

        return dp[-1]

    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]

    # Case 1: Rob the first house, so we cannot rob the last house
    case1 = rob(nums[:-1])

    # Case 2: Rob the last house, so we cannot rob the first house
    case2 = rob(nums[1:])

    return max(case1, case2)
```

