def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def is_palindrome(num):
    return str(num) == str(num)[::-1]

def palindromic_primes(n):
    result = []
    for num in range(2, n + 1):
        if is_prime(num) and is_palindrome(num):
            result.append(num)
    return result
