        for x in range(9):
            if board[row][x] == num or board[x][col] == num:
                return False

        start_row, start_col = 3 * (row // 3), 3 * (col // 3)
        for i in range(3):
            for j in range(3):
                if board[i + start_row][j + start_col] == num:
                    return False

        return True

    def solve(board):
        empty = find_empty(board)
        if not empty:
            return True
        else:
            row, col = empty

        for num in range(1, 10):
            if is_valid(board, row, col, num):
                board[row][col] = num

                if solve(board):
                    return True

                board[row][col] = 0

        return False

    def find_empty(board):
        for i in range(9):
            for j in range(9):
                if board[i][j] == 0:
                    return (i, j)
        return None

    solve(board)
