from typing import List, Tuple

def minimize_max_latency(n: int, links: List[Tuple[int, int, int]]) -> int:
    def can_reach_all(max_latency: int) -> bool:
        from collections import deque

        for i in range(1, n + 1):
            visited = [False] * (n + 1)
            queue = deque([i])
            visited[i] = True

            while queue:
                current = queue.popleft()

                for u, v, w in links:
                    if w <= max_latency:
                        if u == current and not visited[v]:
                            queue.append(v)
                            visited[v] = True
                        if v == current and not visited[u]:
                            queue.append(u)
                            visited[u] = True

            if False in visited[1:]:
                return False

        return True

    if not links or n == 1:
        return 0

    left, right = 1, 100
    result = 100

    while left <= right:
        mid = (left + right) // 2

        if can_reach_all(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result
```

