from typing import List, Tuple

def minimize_max_latency(n: int, links: List[Tuple[int, int, int]]) -> int:
    def can_reach_all_servers(max_latency: int) -> bool:
        from collections import deque

        for start in range(1, n + 1):
            visited = [False] * (n + 1)
            queue = deque([start])
            visited[start] = True

            while queue:
                current = queue.popleft()

                for u, v, w in links:
                    if (u == current or v == current) and w <= max_latency and not visited[v if u == current else u]:
                        visited[v if u == current else u] = True
                        queue.append(v if u == current else u)

            if False in visited[1:]:
                return False

        return True

    if not links or n == 1:
        return 0

    left, right = 1, 100
    result = float('inf')

    while left <= right:
        mid = (left + right) // 2

        if can_reach_all_servers(mid):
            result = min(result, mid)
            right = mid - 1
        else:
            left = mid + 1

    return result
