from typing import Dict, List, Tuple

def prims_algorithm(graph: Dict[int, List[Tuple[int, float]]], start_vertex: int) -> Tuple[List[Tuple[int, int, float]], float]:
    import heapq

    if not graph or start_vertex not in graph:
        return [], 0.0

    mst = []
    total_weight = 0.0
    visited = set()
    min_heap = [(0, start_vertex, -1)]  # (weight, current_vertex, previous_vertex)

    while min_heap:
        weight, current_vertex, previous_vertex = heapq.heappop(min_heap)

        if current_vertex in visited:
            continue

        visited.add(current_vertex)

        if previous_vertex != -1:
            mst.append((previous_vertex, current_vertex, weight))
            total_weight += weight

        for neighbor, edge_weight in graph[current_vertex]:
            if neighbor not in visited:
                heapq.heappush(min_heap, (edge_weight, neighbor, current_vertex))

    return mst, total_weight
```

