def reverse_except_digits(s):
    # Extract digits from the string
    digits = [char for char in s if char.isdigit()]

    # Function to get the next digit from the list
    def get_next_digit():
        if digits:
            return digits.pop()
        return ''

    # Build the result string
    result = ''
    for char in s:
        if char.isdigit():
            result += char
        else:
            result += get_next_digit()

    return result
