def reverse_except_digits(s):
    digits = [char for char in s if char.isdigit()]
    result = list(s)

    digit_index = len(digits) - 1

    for i in range(len(result)):
        if result[i].isdigit():
            result[i] = digits[digit_index]
            digit_index -= 1

    return ''.join(result)
