def depth_first_search(graph: dict, start: any) -> list:
    visited = set()
    result = []

    def dfs(node):
        if node not in visited:
            visited.add(node)
            result.append(node)
            for neighbor in graph[node]:
                dfs(neighbor)

    dfs(start)
    return result
```

