def can_dry_reservoir(rains: List[int]) -> bool:
    # Dictionary to store the last day it rained for each lake
    last_rain_day = {}
    # List to store the days with no rain
    sunny_days = []

    for day, rain in enumerate(rains):
        if rain < 0:
            lake = -rain
            if lake in last_rain_day:
                # If the lake has rained before, find the next sunny day to dry it
                index = bisect_left(sunny_days, last_rain_day[lake])
                if index == len(sunny_days):
                    return False
                else:
                    sunny_days.pop(index)
            last_rain_day[lake] = day
        elif rain > 0:
            # Store the day with no rain
            sunny_days.append(day)

    return True
