print(find_prime_factors(29))  # Should return [29]
print(find_prime_factors(60))  # Should return [2, 2, 3, 5]
print(find_prime_factors(7))   # Should return [7]
print(find_prime_factors(100)) # Should return [2, 2, 5, 5]
