from typing import List

def is_valid_inventory_sequence(operations: List[str]) -> bool:
    add_stack = []

    for operation in operations:
        if operation.startswith('add:'):
            item_type = operation.split(':')[1]
            add_stack.append(item_type)
        elif operation.startswith('remove:'):
            item_type = operation.split(':')[1]
            if not add_stack or add_stack[-1] != item_type:
                return False
            add_stack.pop()

    return len(add_stack) == 0
