def compress_string(s: str) -> str:
    if not s:
        return ""

    compressed = ""
    i = 0
    while i < len(s):
        count = 1
        while i + 1 < len(s) and s[i] == s[i + 1]:
            i += 1
            count += 1
        compressed += s[i] + (str(count) if count > 1 else "")
        i += 1

    return compressed

def decompress_string(s: str) -> str:
    if not s:
        return ""

    decompressed = ""
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        if i < len(s) and s[i].isdigit():
            count = ""
            while i < len(s) and s[i].isdigit():
                count += s[i]
                i += 1
            decompressed += char * int(count)
        else:
            decompressed += char

    return decompressed
```

