def common_words(sentences):
    if not sentences:
        return []

    # Helper function to extract words from a sentence
    def extract_words(sentence):
        words = []
        word = ''
        for char in sentence:
            if char.isalnum():
                word += char
            else:
                if word:
                    words.append(word.lower())
                    word = ''
        if word:
            words.append(word.lower())
        return words

    # Extract words from the first sentence
    if not sentences[0]:
        return []

    words_count = {}
    for word in extract_words(sentences[0]):
        words_count[word] = 1

    # Count words in the remaining sentences
    for sentence in sentences[1:]:
        if not sentence:
            continue

        current_words = {}
        for word in extract_words(sentence):
            if word in words_count:
                if word in current_words:
                    current_words[word] += 1
                else:
                    current_words[word] = 1

        # Update words_count to keep only common words
        for word in list(words_count.keys()):
            if word not in current_words or current_words[word] != words_count[word]:
                del words_count[word]

    # Return the list of common words
    return list(words_count.keys())
```

