import re

def common_words(sentences):
    if not sentences:
        return []

    # Convert all sentences to lower case to ensure case-insensitivity
    sentences = [sentence.lower() for sentence in sentences]

    # Use a dictionary to count occurrences of each word
    word_count = {}

    for sentence in sentences:
        # Use regular expression to find words (sequences of alphanumeric characters)
        words = re.findall(r'\b\w+\b', sentence)
        for word in words:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1

    # Find the maximum count of words
    max_count = max(word_count.values()) if word_count else 0

    # Collect words that appear in every sentence
    common = [word for word, count in word_count.items() if count == max_count]

    return common
