    word_count = {}
    for word in extract_words(sentences[0]):
        word_count[word] = 1

    # Count occurrences of each word in the remaining sentences
    for sentence in sentences[1:]:
        words = extract_words(sentence)
        for word in words:
            if word in word_count:
                word_count[word] += 1

    # Find words that appear in every sentence
    common = [word for word, count in word_count.items() if count == len(sentences)]

    return common
