def common_words(sentences):
    if not sentences:
        return []

    # Helper function to extract words from a sentence
    def extract_words(sentence):
        words = []
        word = ""
        for char in sentence:
            if char.isalnum():
                word += char
            else:
                if word:
                    words.append(word.lower())
                    word = ""
        if word:
            words.append(word.lower())
        return words

    # Initialize a set with words from the first sentence
    common = set(extract_words(sentences[0]))

    # Intersect with words from the rest of the sentences
    for sentence in sentences[1:]:
        current_words = set(extract_words(sentence))
        common.intersection_update(current_words)

    return list(common)
