    n = len(matrix)
    main_diagonal_sum = 0
    secondary_diagonal_sum = 0

    for i in range(n):
        main_diagonal_sum += matrix[i][i]
        secondary_diagonal_sum += matrix[i][n - i - 1]

    return abs(main_diagonal_sum - secondary_diagonal_sum)
