def simple_interpreter(instructions: str) -> int:
    result = 0

    for instruction in instructions.split('\n'):
        if instruction.startswith('result ='):
            result = int(instruction.split('=')[1].strip())
        elif instruction.startswith('result +='):
            result += int(instruction.split('+=')[1].strip())
        elif instruction.startswith('result -='):
            result -= int(instruction.split('-=')[1].strip())

    return result
