def largest_common_subsequence(lists: list[list[int]]) -> list[int]:
    if not lists:
        return []

    # Start with the first list as the initial common subsequence
    common_subsequence = lists[0]

    # Iterate through the rest of the lists
    for lst in lists[1:]:
        temp = []
        for item in common_subsequence:
            if item in lst:
                temp.append(item)
                # Move the pointer in the current list to the next occurrence of the item
                index = lst.index(item) + 1
                while index < len(lst) and lst[index] != item:
                    index += 1
                if index < len(lst):
                    lst = lst[index:]
                else:
                    lst = []
                    break
        common_subsequence = temp

        # If at any point the common subsequence becomes empty, return it immediately
        if not common_subsequence:
            return []

    return common_subsequence
```

