from typing import List

def optimal_delivery_route(n: int, distances: List[List[int]]) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(mask, pos):
        if mask == (1 << n) - 1:
            return distances[pos][0]

        min_distance = float('inf')
        for city in range(n):
            if not (mask & (1 << city)):
                min_distance = min(min_distance, distances[pos][city] + dp(mask | (1 << city), city))

        return min_distance

    return dp(1, 0)
```

