from typing import List

def optimal_delivery_route(n: int, distances: List[List[int]]) -> int:
    if n == 1:
        return 0

    # Initialize the DP table
    dp = [[float('inf')] * (1 << n) for _ in range(n)]

    # Base case: starting from the depot (0) with no other locations visited
    dp[0][1] = 0

    # Iterate over all possible subsets of locations
    for mask in range(1, 1 << n):
        for u in range(n):
            if not (mask & (1 << u)):
                continue

            for v in range(n):
                if v == u or not (mask & (1 << v)):
                    continue

                new_mask = mask | (1 << v)
                dp[v][new_mask] = min(dp[v][new_mask], dp[u][mask] + distances[u][v])

    # Find the minimum distance to return to the depot (0) from any location with all locations visited
    min_distance = float('inf')
    for u in range(1, n):
        min_distance = min(min_distance, dp[u][(1 << n) - 1] + distances[u][0])

    return min_distance
