        node1 = self.search_node(self.root, value1)
        node2 = self.search_node(self.root, value2)

        if node1 is None or node2 is None:
            return None

        return self._lca_recursive(self.root, value1, value2).value

    def _lca_recursive(self, current_node, value1, value2):
        if current_node is None:
            return None

        if current_node.value > value1 and current_node.value > value2:
            return self._lca_recursive(current_node.left, value1, value2)

        if current_node.value < value1 and current_node.value < value2:
            return self._lca_recursive(current_node.right, value1, value2)

