def optimize_shelf_stacks(n_shelves: int, max_height: int, n_items: int) -> int:
    if n_items == 0:
        return 0

    if n_items <= max_height:
        return 1

    if n_shelves == 1:
        return (n_items + max_height - 1) // max_height

    min_stacks = float('inf')

    for i in range(1, n_items + 1):
        if i > max_height:
            break

        stacks = 1 + optimize_shelf_stacks(n_shelves - 1, max_height, n_items - i)
        if stacks < min_stacks:
            min_stacks = stacks

    return min_stacks
