    max_length = 1
    current_length = 1

    for i in range(1, len(arr)):
        if i == 1:
            diff = arr[i] - arr[i - 1]
        if arr[i] - arr[i - 1] == diff:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 2
            diff = arr[i] - arr[i - 1]

    return max_length
