from collections import deque

def orangesRotting(grid):
    if not grid:
        return -1

    rows, cols = len(grid), len(grid[0])
    queue = deque()
    fresh_oranges = 0

    # Initialize the queue with all the rotten oranges and count the fresh oranges
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 2:
                queue.append((i, j))
            elif grid[i][j] == 1:
                fresh_oranges += 1

    if fresh_oranges == 0:
        return 0

    minutes = 0

    # Directions for the 4 possible movements (up, down, left, right)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        for _ in range(len(queue)):
            x, y = queue.popleft()

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                # Check if the new position is within bounds and is a fresh orange
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1:
                    grid[nx][ny] = 2  # Mark the orange as rotten
                    queue.append((nx, ny))
                    fresh_oranges -= 1

        minutes += 1

    # If there are still fresh oranges left, it's impossible to rot them
    if fresh_oranges > 0:
        return -1

    # Return the minutes minus 1 because the last increment happens after the last orange is rotten
    return minutes - 1
```

