def reverse_palindromes(lst):
    def is_palindrome(s):
        s = s.lower()
        left, right = 0, len(s) - 1
        while left < right:
            if s[left] != s[right]:
                return False
            left += 1
            right -= 1
        return True

    def reverse_string(s):
        reversed_s = ""
        for char in s:
            reversed_s = char + reversed_s
        return reversed_s

    result = []
    for item in lst:
        if is_palindrome(item):
            result.append(reverse_string(item))
        else:
            result.append(item)
    return result
```

