def sort_and_count_odd(num_list):
    sorted_list = []
    odd_count = 0

    for num in num_list:
        if num is None or type(num) not in [int, float] or isinstance(num, bool):
            continue
        else:
            sorted_list.append(num)
            if isinstance(num, int) and num % 2 != 0:
                odd_count += 1

    sorted_list.sort()

    return (sorted_list, odd_count)

