from typing import Optional

class FileSystemSimulator:
    def __init__(self) -> None:
        self.files = {}
        self.directories = {}

    def create(self, id: int, size: int, parent_id: Optional[int] = None, is_file: bool = True) -> None:
        if is_file:
            self.files[id] = size
        else:
            self.directories[id] = {'size': 0, 'children': {}}

        if parent_id is not None:
            if parent_id in self.directories:
                self.directories[parent_id]['children'][id] = True
                if not is_file:
                    self.directories[id]['parent'] = parent_id

    def delete(self, id: int) -> None:
        if id in self.files:
            del self.files[id]
        elif id in self.directories:
            for child_id in self.directories[id]['children']:
                self.delete(child_id)
            del self.directories[id]

    def get_size(self, id: int) -> int:
        if id in self.files:
            return self.files[id]
        elif id in self.directories:
            if 'size' in self.directories[id]:
                return self.directories[id]['size']
            else:
                total_size = 0
                for child_id in self.directories[id]['children']:
                    total_size += self.get_size(child_id)
                self.directories[id]['size'] = total_size
                return total_size
        return 0
