from typing import Optional

class FileSystemSimulator:
    def __init__(self) -> None:
        self.files = {}
        self.directories = {}

    def create(self, id: int, size: int, parent_id: Optional[int] = None, is_file: bool = True) -> None:
        if is_file:
            self.files[id] = size
        else:
            self.directories[id] = {'size': 0, 'contents': {}}

        if parent_id is not None:
            if parent_id in self.directories:
                self.directories[parent_id]['contents'][id] = id
                if not is_file:
                    self.directories[id]['parent'] = parent_id
            else:
                raise ValueError("Parent directory does not exist")

    def delete(self, id: int) -> None:
        if id in self.files:
            del self.files[id]
        elif id in self.directories:
            self._delete_directory(id)

    def get_size(self, id: int) -> int:
        if id in self.files:
            return self.files[id]
        elif id in self.directories:
            return self._get_directory_size(id)
        else:
            raise ValueError("ID does not exist")

    def _delete_directory(self, id: int) -> None:
        if id in self.directories:
            for content_id in self.directories[id]['contents'].values():
                if content_id in self.files:
                    del self.files[content_id]
                elif content_id in self.directories:
                    self._delete_directory(content_id)
            del self.directories[id]

    def _get_directory_size(self, id: int) -> int:
        if id in self.directories:
            size = self.directories[id]['size']
            for content_id in self.directories[id]['contents'].values():
                if content_id in self.files:
                    size += self.files[content_id]
                elif content_id in self.directories:
                    size += self._get_directory_size(content_id)
            return size
        else:
            raise ValueError("ID does not exist")
