from typing import Optional

class FileSystemSimulator:
    def __init__(self) -> None:
        self.files_and_dirs = {}

    def create(self, id: int, size: int, parent_id: Optional[int] = None, is_file: bool = True) -> None:
        if is_file:
            self.files_and_dirs[id] = {'size': size, 'parent_id': parent_id, 'is_file': True}
        else:
            self.files_and_dirs[id] = {'size': 0, 'parent_id': parent_id, 'is_file': False}

    def delete(self, id: int) -> None:
        if id in self.files_and_dirs:
            if not self.files_and_dirs[id]['is_file']:
                self._delete_directory(id)
            else:
                del self.files_and_dirs[id]

    def get_size(self, id: int) -> int:
        if id not in self.files_and_dirs:
            return 0

        if self.files_and_dirs[id]['is_file']:
            return self.files_and_dirs[id]['size']

        return self._get_directory_size(id)

    def _delete_directory(self, id: int) -> None:
        if id not in self.files_and_dirs:
            return

        if not self.files_and_dirs[id]['is_file']:
            for key, value in list(self.files_and_dirs.items()):
                if value['parent_id'] == id:
                    self._delete_directory(key)

            del self.files_and_dirs[id]

    def _get_directory_size(self, id: int) -> int:
        if id not in self.files_and_dirs:
            return 0

        if self.files_and_dirs[id]['is_file']:
            return self.files_and_dirs[id]['size']

        size = 0
        for key, value in self.files_and_dirs.items():
            if value['parent_id'] == id:
                size += self._get_directory_size(key)

        return size + self.files_and_dirs[id]['size']
