    def __init__(self) -> None:
        self.files = {}
        self.directories = {}

    def create(self, id: int, size: int, parent_id: Optional[int] = None, is_file: bool = True) -> None:
        if is_file:
            self.files[id] = size
        else:
            self.directories[id] = {'size': 0, 'children': {}}

        if parent_id is not None:
            if parent_id in self.directories:
                self.directories[parent_id]['children'][id] = is_file
            else:
                raise ValueError("Parent directory does not exist")

    def delete(self, id: int) -> None:
        if id in self.files:
            del self.files[id]
        elif id in self.directories:
            for child_id in list(self.directories[id]['children'].keys()):
                self.delete(child_id)
            del self.directories[id]
        else:
            raise ValueError("ID does not exist")

    def get_size(self, id: int) -> int:
        if id in self.files:
            return self.files[id]
        elif id in self.directories:
            size = self.directories[id]['size']
            for child_id, is_file in self.directories[id]['children'].items():
                if is_file:
                    size += self.files[child_id]
                else:
                    size += self.get_size(child_id)
