def nested_list_depth(nested_list: list) -> int:
    """ Calculate the maximum depth of a given nested list. """
    if not nested_list:
        return 1

    max_depth = 0
    for element in nested_list:
        if isinstance(element, list):
            max_depth = max(max_depth, nested_list_depth(element))

    return max_depth + 1
```

