from typing import List

def find_min_diff(num_list: List[int], n: int) -> int:
    num_list.sort()
    min_diff = float('inf')

    for i in range(len(num_list) - 1):
        diff = abs(num_list[i] - num_list[i + 1])
        if diff < min_diff:
            min_diff = diff
        if i >= n - 2:
            break

    return min_diff
