from typing import List

def find_buildings_with_ocean_view(heights: List[int]) -> List[int]:
    if not heights:
        return []

    result = [len(heights) - 1]  # The last building always sees the ocean
    max_height = heights[-1]

    for i in range(len(heights) - 2, -1, -1):
        if heights[i] > max_height:
            result.append(i)
            max_height = heights[i]

    return sorted(result)
```

