def find_buildings_with_ocean_view(heights: List[int]) -> List[int]:
    if not heights:
        return []

    result = [len(heights) - 1]  # The last building can always see the ocean

    for i in range(len(heights) - 2, -1, -1):
        if heights[i] > heights[result[-1]]:
            result.append(i)

    return result[::-1]  # Reverse the list to get the indices in ascending order
```

