def can_be_converted(s1, s2):
    if s1 == s2:
        return True

    diff = []
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            diff.append(i)

    if len(diff) != 2:
        return False

    i, j = diff
    return s1[i] == s2[j] and s1[j] == s2[i]
