def longest_contiguous_subarray(nums):
    if not nums:
        return (0, None)

    max_length = 1
    current_length = 1
    max_value = nums[0]
    current_value = nums[0]

    for i in range(1, len(nums)):
        if nums[i] == current_value:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                max_value = current_value
            current_value = nums[i]
            current_length = 1

    if current_length > max_length:
        max_length = current_length
        max_value = current_value

    return (max_length, max_value)
```

