def categorize_words_by_length(words):
    word_dict = {}

    for word in words:
        length = len(word)
        if length not in word_dict:
            word_dict[length] = []
        word_dict[length].append(word)

    for key in word_dict:
        word_dict[key].sort()

    return word_dict
