def longest_subarray_equal_even_odd(nums):
    if not nums:
        return 0

    count_map = {0: -1}  # Initialize map with count 0 at index -1
    count = 0  # Initialize count of even and odd numbers
    max_length = 0  # Initialize the maximum length of subarray

    for i in range(len(nums)):
        if nums[i] % 2 == 0:
            count += 1  # Increment count for even number
        else:
            count -= 1  # Decrement count for odd number

        if count in count_map:
            # If the count is already in the map, it means there is a subarray
            # with equal number of even and odd numbers
            max_length = max(max_length, i - count_map[count])
        else:
            # If the count is not in the map, store the count with the current index
            count_map[count] = i

    return max_length
```

