def longest_subarray_equal_even_odd(nums):
    if not nums:
        return 0

    count_diff = {0: -1}  # Initialize with 0 difference at index -1
    count_even = 0
    count_odd = 0
    max_length = 0

    for i, num in enumerate(nums):
        if num % 2 == 0:
            count_even += 1
        else:
            count_odd += 1

        diff = count_even - count_odd

        if diff in count_diff:
            max_length = max(max_length, i - count_diff[diff])
        else:
            count_diff[diff] = i

    return max_length
```

