def fibonacci_efficient(n: int) -> int:
    if n <= 1:
        return n

    def multiply(mat1, mat2):
        x = mat1[0][0] * mat2[0][0] + mat1[0][1] * mat2[1][0]
        y = mat1[0][0] * mat2[0][1] + mat1[0][1] * mat2[1][1]
        z = mat1[1][0] * mat2[0][0] + mat1[1][1] * mat2[1][0]
        w = mat1[1][0] * mat2[0][1] + mat1[1][1] * mat2[1][1]

        res = [[x, y], [z, w]]
        return res

    def power(mat, n):
        if n == 1:
            return mat
        elif n % 2 == 0:
            temp = power(mat, n // 2)
            return multiply(temp, temp)
        else:
            temp = power(mat, (n - 1) // 2)
            temp = multiply(temp, temp)
            return multiply(temp, mat)

    F = [[1, 1], [1, 0]]
    if n == 0:
        return 0
    power(F, n - 1)

    return F[0][0]
