def fibonacci_efficient(n: int) -> int:
    if n <= 1:
        return n

    def multiply(mat1, mat2, res):
        for i in range(3):
            for j in range(3):
                res[i][j] = 0
                for k in range(3):
                    res[i][j] += mat1[i][k] * mat2[k][j]

    def matrix_power(mat, n):
        if n == 0 or n == 1:
            return

        temp = [[0, 1], [1, 1]]

        matrix_power(mat, n // 2)
        multiply(mat, mat, mat)

        if n % 2 != 0:
            multiply(mat, temp, mat)

    def fibonacci_matrix(n):
        F = [[1, 1], [1, 0]]
        if n == 0:
            return 0
        matrix_power(F, n - 1)
        return F[0][0]

    return fibonacci_matrix(n)
