def is_valid_rotation(matrix):
    def rotate(matrix):
        n = len(matrix)
        rotated = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                rotated[j][n - 1 - i] = matrix[i][j]
        return rotated

    def is_equal(matrix1, matrix2):
        for i in range(len(matrix1)):
            for j in range(len(matrix1)):
                if matrix1[i][j] != matrix2[i][j]:
                    return False
        return True

    original = matrix
    if is_equal(original, rotate(rotate(rotate(original)))):
        return True
    if is_equal(original, rotate(rotate(original))):
        return True
    if is_equal(original, rotate(original)):
        return True
    return False
```

