from typing import List

def determinant(matrix: List[List[int]]) -> int:
    n = len(matrix)

    # Base case: if the matrix is 2x2
    if n == 2:
        return (matrix[0][0] * matrix[1][1]) - (matrix[0][1] * matrix[1][0])

    det = 0

    # Iterate through the first row
    for j in range(n):
        # Create a minor matrix by excluding the first row and the j-th column
        minor = []
        for i in range(1, n):
            row = []
            for k in range(n):
                if k != j:
                    row.append(matrix[i][k])
            minor.append(row)

        # Recursively calculate the determinant of the minor matrix
        if j % 2 == 0:
            det += matrix[0][j] * determinant(minor)
        else:
            det -= matrix[0][j] * determinant(minor)

    return det
