from collections import defaultdict, deque

def find_order_of_courses(courses, prerequisites):
    if not courses or not prerequisites:
        return []

    # Create a graph and in-degree dictionary
    graph = defaultdict(list)
    in_degree = {i: 0 for i in range(courses)}

    # Build the graph and in-degree dictionary
    for course, prereq in prerequisites:
        graph[prereq].append(course)
        in_degree[course] += 1

    # Find all courses with no prerequisites
    queue = deque([course for course in in_degree if in_degree[course] == 0])

    # List to store the order of courses
    order = []

    while queue:
        if len(queue) > 1:
            return []  # More than one course with no prerequisites, impossible to complete

        course = queue.popleft()
        order.append(course)

        for neighbor in graph[course]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != courses:
        return []  # Cycle detected, impossible to complete all courses

    return order
```

