def is_valid_roman_numeral(numeral: str) -> bool:
    if not numeral:
        return False

    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    prev_value = 0
    count = 0

    for char in reversed(numeral):
        if char not in roman_map:
            return False

        current_value = roman_map[char]

        if current_value < prev_value:
            if current_value == 5 * prev_value or current_value == 10 * prev_value:
                count += 1
                if count > 1:
                    return False
            else:
                return False
        else:
            count = 1

        prev_value = current_value

    return True
