def max_tips(orders: list, tips: list, serve_time: list) -> int:
    if not orders or not tips or not serve_time:
        raise ValueError("All input lists must not be empty")

    if len(orders) != len(tips) or len(orders) != len(serve_time):
        raise ValueError("All input lists must have the same length")

    if any(tip < 0 for tip in tips):
        raise ValueError("All tips must be non-negative")

    if any(start < 0 or end < 0 for start, end in serve_time):
        raise ValueError("All serve times must be non-negative")

    n = len(orders)
    jobs = [(start, end, tips[i]) for i, (start, end) in enumerate(serve_time)]
    jobs.sort(key=lambda x: x[1])  # Sort by end time

    dp = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        next_valid = i + 1
        while next_valid < n and jobs[next_valid][0] < jobs[i][1]:
            next_valid += 1

        dp[i] = max(jobs[i][2] + (dp[next_valid] if next_valid < n else 0), dp[i + 1])

    return dp[0]
