    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        for j in range(i - 1, -1, -1):
            if jobs[j][0][1] <= jobs[i - 1][0][0]:
                dp[i] = max(dp[i], dp[j] + jobs[i - 1][1])
                break

