    for i in range(n - 1, -1, -1):
        current_max = 0
        for j in range(i + 1, n):
            if serve_time[order_indices[j]][0] >= serve_time[order_indices[i]][1]:
                current_max = max(current_max, dp[j])
        dp[i] = tips[order_indices[i]] + current_max

    return dp[0]
