def max_tips(orders: list, tips: list, serve_time: list) -> int:
    if not orders or not tips or not serve_time:
        raise ValueError("All input lists must be non-empty")

    if len(orders) != len(tips) or len(orders) != len(serve_time):
        raise ValueError("All input lists must have the same length")

    for tip in tips:
        if tip < 0:
            raise ValueError("Tip amounts must be non-negative")

    for start, end in serve_time:
        if start < 0 or end < 0 or start > 24 or end > 24:
            raise ValueError("Serve times must be in 24-hour format and non-negative")

    n = len(orders)
    jobs = []

    for i in range(n):
        jobs.append((serve_time[i][0], serve_time[i][1], tips[i], orders[i]))

    jobs.sort(key=lambda x: x[1])  # Sort by end time

    dp = [0] * (n + 1)
    prev_job_index = -1

    for i in range(1, n + 1):
        dp[i] = dp[i - 1]  # Exclude the current job

        for j in range(i - 1, -1, -1):
            if jobs[j][1] <= jobs[i - 1][0]:
                prev_job_index = j
                break

        if prev_job_index != -1:
            dp[i] = max(dp[i], dp[prev_job_index + 1] + jobs[i - 1][2])

    return dp[n]
```

