def longest_subarray(arr, k):
    if not arr:
        return 0

    arr.sort()
    left = 0
    max_length = 0

    for right in range(len(arr)):
        while arr[right] - arr[left] > k:
            left += 1
        max_length = max(max_length, right - left + 1)

    return max_length
```

