from typing import List, Tuple

def flag_fraudulent_transactions(
    transactions: List[Tuple[str, int]],
    window: int
) -> List[str]:
    flagged_ids = []
    timestamp_dict = {}

    for transaction_id, timestamp in transactions:
        if transaction_id in timestamp_dict:
            if timestamp - timestamp_dict[transaction_id] <= window:
                if transaction_id not in flagged_ids:
                    flagged_ids.append(transaction_id)
            timestamp_dict[transaction_id] = timestamp
        else:
            timestamp_dict[transaction_id] = timestamp

    return flagged_ids
