def is_happy_string(s):
    vowels = "aeiouAEIOU"
    num_vowels = 0
    num_consonants = 0

    for char in s:
        if char.isalpha():
            if char in vowels:
                num_vowels += 1
            else:
                num_consonants += 1

    return num_vowels > 2 * num_consonants
```

