def longest_subarray_with_sum(nums, target):
    sum_dict = {0: -1}
    current_sum = 0
    max_length = 0
    start_index = 0
    result = []

    for i, num in enumerate(nums):
        current_sum += num

        if (current_sum - target) in sum_dict:
            if i - sum_dict[current_sum - target] > max_length:
                max_length = i - sum_dict[current_sum - target]
                start_index = sum_dict[current_sum - target] + 1

        if current_sum not in sum_dict:
            sum_dict[current_sum] = i

    if max_length > 0:
        result = nums[start_index:start_index + max_length]

    return result
```

